alter table app.profiles enable row level security; alter table app.organizations enable row level security; alter table app.organization_members enable row level security;
create policy profiles_select_own_or_superadmin on app.profiles for select to authenticated using((select auth.uid())=id or (select operations.is_superadmin())); create policy profiles_update_own on app.profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
create policy organizations_select_member on app.organizations for select to authenticated using(operations.is_org_member(id)); create policy organizations_insert_creator on app.organizations for insert to authenticated with check((select auth.uid()) is not null and created_by=(select auth.uid())); create policy organizations_update_admin on app.organizations for update to authenticated using(operations.has_org_admin(id)) with check(operations.has_org_admin(id)); create policy organizations_delete_owner on app.organizations for delete to authenticated using(operations.is_superadmin() or exists(select 1 from app.organization_members m where m.organization_id=id and m.user_id=(select auth.uid()) and m.role='organization_owner'));
create policy members_select_org on app.organization_members for select to authenticated using(operations.is_org_member(organization_id)); create policy members_insert_admin on app.organization_members for insert to authenticated with check(operations.has_org_admin(organization_id)); create policy members_update_admin on app.organization_members for update to authenticated using(operations.has_org_admin(organization_id)) with check(operations.has_org_admin(organization_id)); create policy members_delete_admin on app.organization_members for delete to authenticated using(operations.has_org_admin(organization_id));
do $e$ declare r record;begin for r in select * from (values ('app','projects'),('app','project_members'),('app','project_notes'),('app','conversations'),('app','messages'),('security','engagements'),('security','authorization_records'),('security','engagement_scope'),('security','findings'),('security','finding_evidence'),('security','finding_evidence_versions'),('artifacts','files'),('artifacts','file_versions'),('artifacts','file_chunks'),('ai','agent_runs'),('ai','agent_run_steps'),('ai','agent_checkpoints'),('ai','tool_runs'),('ai','generation_requests'),('ai','memory_items'),('reports','reports'),('reports','report_versions'),('reports','report_sections'),('usage','usage_events'),('usage','usage_daily'),('billing','subscriptions'),('billing','quotas')) as t(s,n) loop execute format('alter table %I.%I enable row level security',r.s,r.n);execute format('create policy %I on %I.%I for select to authenticated using (operations.is_org_member(organization_id))',r.n||'_tenant_select',r.s,r.n);end loop;end$e$;
create policy projects_insert_member on app.projects for insert to authenticated with check(operations.has_org_write(organization_id) and created_by=(select auth.uid())); create policy projects_update_member on app.projects for update to authenticated using(operations.has_org_write(organization_id)) with check(operations.has_org_write(organization_id)); create policy projects_delete_admin on app.projects for delete to authenticated using(operations.has_org_admin(organization_id));
create policy project_members_insert_admin on app.project_members for insert to authenticated with check(operations.has_org_admin(organization_id)); create policy project_members_update_admin on app.project_members for update to authenticated using(operations.has_org_admin(organization_id)) with check(operations.has_org_admin(organization_id)); create policy project_members_delete_admin on app.project_members for delete to authenticated using(operations.has_org_admin(organization_id));
create policy notes_insert_member on app.project_notes for insert to authenticated with check(operations.has_org_write(organization_id) and created_by=(select auth.uid())); create policy notes_update_member on app.project_notes for update to authenticated using(operations.has_org_write(organization_id)) with check(operations.has_org_write(organization_id)); create policy notes_delete_member on app.project_notes for delete to authenticated using(operations.has_org_write(organization_id));
create policy conversations_insert_self on app.conversations for insert to authenticated with check(operations.has_org_write(organization_id) and user_id=(select auth.uid())); create policy conversations_update_self on app.conversations for update to authenticated using(operations.has_org_write(organization_id) and user_id=(select auth.uid())) with check(operations.has_org_write(organization_id) and user_id=(select auth.uid())); create policy conversations_delete_self on app.conversations for delete to authenticated using(operations.has_org_write(organization_id) and user_id=(select auth.uid()));
create policy messages_insert_user_only on app.messages for insert to authenticated with check(operations.has_org_write(organization_id) and role='user' and user_id=(select auth.uid())); create policy messages_update_user_only on app.messages for update to authenticated using(operations.has_org_write(organization_id) and role='user' and user_id=(select auth.uid())) with check(operations.has_org_write(organization_id) and role='user' and user_id=(select auth.uid())); create policy messages_delete_user_only on app.messages for delete to authenticated using(operations.has_org_write(organization_id) and role='user' and user_id=(select auth.uid()));
create policy engagements_insert_member on security.engagements for insert to authenticated with check(operations.has_org_write(organization_id) and created_by=(select auth.uid()) and status in ('draft','ready')); create policy engagements_update_member on security.engagements for update to authenticated using(operations.has_org_write(organization_id)) with check(operations.has_org_write(organization_id) and status in ('draft','ready','paused','completed','cancelled')); create policy engagements_delete_admin on security.engagements for delete to authenticated using(operations.has_org_admin(organization_id));
create policy authorization_insert_admin on security.authorization_records for insert to authenticated with check(operations.has_org_admin(organization_id)); create policy authorization_update_admin on security.authorization_records for update to authenticated using(operations.has_org_admin(organization_id)) with check(operations.has_org_admin(organization_id)); create policy authorization_delete_admin on security.authorization_records for delete to authenticated using(operations.has_org_admin(organization_id));
create policy scope_insert_admin on security.engagement_scope for insert to authenticated with check(operations.has_org_admin(organization_id)); create policy scope_update_admin on security.engagement_scope for update to authenticated using(operations.has_org_admin(organization_id)) with check(operations.has_org_admin(organization_id)); create policy scope_delete_admin on security.engagement_scope for delete to authenticated using(operations.has_org_admin(organization_id));
create policy findings_insert_member on security.findings for insert to authenticated with check(operations.has_org_write(organization_id) and created_by=(select auth.uid())); create policy findings_update_member on security.findings for update to authenticated using(operations.has_org_write(organization_id)) with check(operations.has_org_write(organization_id)); create policy findings_delete_admin on security.findings for delete to authenticated using(operations.has_org_admin(organization_id));
create policy evidence_insert_member on security.finding_evidence for insert to authenticated with check(operations.has_org_write(organization_id)); create policy evidence_versions_insert_member on security.finding_evidence_versions for insert to authenticated with check(operations.has_org_write(organization_id) and (created_by is null or created_by=(select auth.uid())));
create policy reports_insert_member on reports.reports for insert to authenticated with check(operations.has_org_write(organization_id) and created_by=(select auth.uid())); create policy reports_update_member on reports.reports for update to authenticated using(operations.has_org_write(organization_id)) with check(operations.has_org_write(organization_id)); create policy reports_delete_admin on reports.reports for delete to authenticated using(operations.has_org_admin(organization_id)); create policy report_versions_insert_member on reports.report_versions for insert to authenticated with check(operations.has_org_write(organization_id) and (created_by is null or created_by=(select auth.uid()))); create policy report_sections_insert_member on reports.report_sections for insert to authenticated with check(operations.has_org_write(organization_id)); create policy report_sections_update_member on reports.report_sections for update to authenticated using(operations.has_org_write(organization_id)) with check(operations.has_org_write(organization_id));
do $internal$ declare r record;begin for r in select * from (values ('ai','models'),('ai','model_versions'),('ai','model_deployments'),('ai','routing_rules'),('ai','prompt_versions'),('billing','plans'),('operations','feature_flags'),('operations','system_state'),('operations','kill_switches'),('operations','idempotency_keys'),('operations','event_outbox'),('audit','audit_logs'),('launch','waitlist_campaigns'),('launch','waitlist_entries'),('launch','waitlist_referral_events'),('launch','waitlist_invitations'),('launch','waitlist_rate_limits')) as t(s,n) loop execute format('alter table %I.%I enable row level security',r.s,r.n);end loop;end$internal$;
revoke all on all tables in schema app,security,artifacts,ai,reports,usage,billing,launch from anon,authenticated; revoke all on all sequences in schema app,security,artifacts,ai,reports,usage,billing,launch from anon,authenticated; revoke all on all functions in schema app,security,artifacts,ai,reports,usage,billing,launch from anon,authenticated;
grant usage on schema app,security,artifacts,ai,reports,usage,billing to authenticated; grant select on app.profiles to authenticated; grant update(display_name,avatar_url,timezone,updated_at) on app.profiles to authenticated; grant select,insert,update,delete on app.organizations,app.organization_members,app.projects,app.project_members,app.project_notes,app.conversations,app.messages to authenticated; grant select,insert,update,delete on security.engagements,security.authorization_records,security.engagement_scope,security.findings to authenticated; grant select,insert on security.finding_evidence,security.finding_evidence_versions to authenticated; grant select on artifacts.files,artifacts.file_versions,artifacts.file_chunks to authenticated; grant select on ai.agent_runs,ai.agent_run_steps,ai.agent_checkpoints,ai.tool_runs,ai.generation_requests,ai.memory_items to authenticated; grant select,insert,update,delete on reports.reports to authenticated; grant select,insert on reports.report_versions to authenticated; grant select,insert,update on reports.report_sections to authenticated; grant select on usage.usage_events,usage.usage_daily,billing.subscriptions,billing.quotas to authenticated; grant usage on schema launch to anon,authenticated; grant execute on function launch.join_waitlist(text,text,text,text,text,text,text,text) to anon,authenticated;
grant usage on schema app,launch,ai,security,artifacts,reports,usage,billing,operations,audit to service_role; grant all on all tables in schema app,launch,ai,security,artifacts,reports,usage,billing,operations,audit to service_role; grant all on all sequences in schema app,launch,ai,security,artifacts,reports,usage,billing,operations,audit to service_role; grant execute on all functions in schema app,launch,ai,security,artifacts,reports,usage,billing,operations,audit to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('project-artifacts','project-artifacts',false,104857600,null) on conflict(id) do update set public=false,file_size_limit=104857600;
create policy project_artifacts_select_org on storage.objects for select to authenticated using(bucket_id='project-artifacts' and operations.is_org_member(operations.try_uuid((storage.foldername(name))[1]))); create policy project_artifacts_insert_org on storage.objects for insert to authenticated with check(bucket_id='project-artifacts' and operations.has_org_write(operations.try_uuid((storage.foldername(name))[1]))); create policy project_artifacts_update_org on storage.objects for update to authenticated using(bucket_id='project-artifacts' and operations.has_org_write(operations.try_uuid((storage.foldername(name))[1]))) with check(bucket_id='project-artifacts' and operations.has_org_write(operations.try_uuid((storage.foldername(name))[1]))); create policy project_artifacts_delete_org on storage.objects for delete to authenticated using(bucket_id='project-artifacts' and operations.has_org_admin(operations.try_uuid((storage.foldername(name))[1])));
do $t$ declare r record;begin for r in select * from (values ('app','profiles'),('app','organizations'),('app','organization_members'),('app','projects'),('app','project_notes'),('app','conversations'),('security','engagements'),('security','authorization_records'),('security','findings'),('artifacts','files'),('ai','models'),('ai','model_deployments'),('ai','agent_runs'),('ai','agent_run_steps'),('ai','memory_items'),('reports','reports'),('reports','report_sections'),('billing','plans'),('billing','subscriptions'),('billing','quotas')) as x(s,n) loop execute format('create trigger touch_updated_at before update on %I.%I for each row execute function operations.touch_updated_at()',r.s,r.n);end loop;end$t$;
alter role authenticator set pgrst.db_schemas='public,app,launch,ai,security,artifacts,reports,usage,billing'; notify pgrst,'reload config';
